from html.parser import HTMLParser
from pathlib import Path
import hashlib, json, re

class TextBlocks(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hidden = 0
        self.parts = []
    def handle_starttag(self, tag, attrs):
        if tag in {'script', 'style'}:
            self.hidden += 1
        if tag in {'p', 'li', 'h1', 'h2', 'h3', 'h4', 'tr', 'br'} and not self.hidden:
            self.parts.append('\n')
    def handle_endtag(self, tag):
        if tag in {'script', 'style'} and self.hidden:
            self.hidden -= 1
    def handle_data(self, data):
        if not self.hidden:
            self.parts.append(data)

root = Path('products/services/existing-package-marketplace-checkout')
sources = [
    ('payments', 'itch-creator-payments.html', 'e0ce3e28bcf9b12f6bd71f90317f4feaf711bedbc67afab19456cf2c35e9f213'),
    ('quality-guidelines', 'itch-quality-guidelines.html', '5f18e84f0ef13ddf11bec9601ea5fa19304f1adb1294db0bfb462f260532420b'),
]
keywords = re.compile(r'generative|artificial intelligence|\bAI\b|disclos|utilit|software|Canada|Canadian|Stripe|PayPal|Payoneer|payout|tax interview|verification|revenue shar|transaction fee|minimum payout|collected by', re.I)
result = {'scope': 'Passage pointers for verification in the original captures. Keyword matches and omissions do not establish policy or eligibility.', 'sources': []}
for slug, name, receipt_hash in sources:
    raw = (root / 'raw' / name).read_bytes()
    actual_hash = hashlib.sha256(raw).hexdigest()
    parser = TextBlocks()
    parser.feed(raw.decode('utf-8'))
    blocks = [' '.join(line.split()) for line in ''.join(parser.parts).splitlines()]
    blocks = [line for line in blocks if line]
    hits = [i for i, block in enumerate(blocks) if keywords.search(block)]
    selected = sorted({j for i in hits for j in (i - 1, i, i + 1) if 0 <= j < len(blocks)})
    result['sources'].append({'url': 'https://itch.io/docs/creators/' + slug, 'capture': str(root / 'raw' / name), 'sha256': actual_hash, 'receipt_sha256_matches': actual_hash == receipt_hash, 'block_count': len(blocks), 'match_count': len(hits), 'passages': [{'block': i, 'text': blocks[i]} for i in selected]})
output = root / 'itch-first-party-policy-passages.json'
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'artifact': str(output), 'sources': [{k: row[k] for k in ('url', 'receipt_sha256_matches', 'block_count', 'match_count')} for row in result['sources']]}))
